//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error represents a transient fault.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum retry delay, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry after `retry_number` failed attempts.
    pub(crate) fn delay_for_retry(&self, retry_number: u32) -> u64 {
        let multiplier = retry_number.saturating_sub(1).min(63);
        let delay = self.base_delay_ms.saturating_mul(1u64 << multiplier);
        delay.min(self.max_delay_ms)
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempt = 1;

    loop {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempt >= max_attempts => {
                return Err(error)
            }
            Err(_) => {
                sleeper.sleep_ms(config.delay_for_retry(attempt));
                attempt += 1;
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn config(max_attempts: u32) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms: 10,
            max_delay_ms: 25,
        }
    }

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            if calls < 4 {
                Err(RetryError::Transient("temporary failure".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
    }

    #[test]
    fn permanent_errors_return_without_retrying() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid input".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn zero_max_attempts_still_makes_one_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(0), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("unavailable".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("unavailable".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn retry_delay_saturates_without_overflowing() {
        let config = RetryConfig {
            max_attempts: u32::MAX,
            base_delay_ms: u64::MAX,
            max_delay_ms: 123,
        };

        assert_eq!(config.delay_for_retry(u32::MAX), 123);
    }
}

# jobrunner

Small job runner with a pluggable, bounded exponential retry policy.

## Retry policy

`run_job` retries only `RetryError::Transient` failures. Permanent failures
return immediately. `RetryConfig::max_attempts` is the total number of calls,
including the first call. After each retryable failure, the runner waits for a
delay that starts at `base_delay_ms` and doubles after each failure, capped at
`max_delay_ms`.

For example, this configuration attempts a job four times at most and requests
10 ms, 20 ms, and 40 ms delays between attempts:

```rust
use jobrunner::{run_job, RetryConfig, RetryError, Sleeper};

# struct RealSleeper;
# impl Sleeper for RealSleeper { fn sleep_ms(&mut self, _ms: u64) { } }
let config = RetryConfig {
    max_attempts: 4,
    base_delay_ms: 10,
    max_delay_ms: 40,
};
let mut sleeper = RealSleeper;
let result = run_job(&config, &mut sleeper, || Ok::<(), RetryError>(()));
assert_eq!(result, Ok(()));
```

`max_attempts` should be at least 1. A zero value is treated as one attempt.

use jobrunner::{run_job, RetryConfig, RetryError, Sleeper};

#[derive(Default)]
struct RecordingSleeper(Vec<u64>);

impl Sleeper for RecordingSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.0.push(ms);
    }
}

#[test]
fn public_api_retries_transient_failures_and_preserves_signature() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 7,
        max_delay_ms: 10,
    };
    let mut sleeper = RecordingSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        match calls {
            1 | 2 => Err(RetryError::Transient("temporary".to_owned())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.0, vec![7, 10]);
}
